#!/usr/bin/env python3
"""Regenerate index.md from article front matter.

index.md is generated: do not edit it by hand or in PRs.
Usage: python3 scripts/build_index.py [--root .] [--check]
  --check  exit 1 if index.md is out of date instead of rewriting it
"""
import argparse
import re
import sys
from pathlib import Path

import yaml

SECTIONS = [("movements", "Movements"), ("artists", "Artists"), ("works", "Works"),
            ("techniques", "Techniques"), ("themes", "Themes")]
FM_RE = re.compile(r"\A---\s*\n(.*?)\n---\s*\n", re.S)

HEADER = """# Index

<!-- Generated by scripts/build_index.py after every merge to main. Do not edit by hand. -->

Table of contents for the art-history collection, grouped by category.
"""


def entry(path: Path, root: Path):
    m = FM_RE.match(path.read_text(encoding="utf-8"))
    fm = (yaml.safe_load(m.group(1)) if m else None) or {}
    title = str(fm.get("title") or path.stem.replace("-", " ").title())
    period = fm.get("period")
    line = f"- [{title}]({path.relative_to(root).as_posix()})"
    return title.lower(), line + (f" — {period}" if period else "")


def build(root: Path) -> str:
    out = [HEADER]
    total = 0
    for folder, heading in SECTIONS:
        items = sorted(entry(p, root) for p in (root / "articles" / folder).glob("*.md"))
        total += len(items)
        out.append(f"\n## {heading}\n\n")
        out.append("\n".join(line for _, line in items) + "\n" if items else "_No articles yet._\n")
    out.append(f"\n---\n\n{total} article(s).\n")
    return "".join(out)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--root", default=".")
    ap.add_argument("--check", action="store_true")
    args = ap.parse_args()
    root = Path(args.root)
    index = root / "index.md"
    new = build(root)
    old = index.read_text(encoding="utf-8") if index.exists() else ""
    if args.check:
        if old != new:
            print("index.md is out of date; run scripts/build_index.py")
            sys.exit(1)
        print("index.md is up to date")
        return
    if old != new:
        index.write_text(new, encoding="utf-8")
        print("index.md updated")
    else:
        print("index.md already up to date")


if __name__ == "__main__":
    main()
